motions = [("동전 커짐", 0.40), ("텍스트 올라옴", 0.30), ("버튼 올라옴", 0.30)]

def timeline(mode, delay=0.1):
    t, out = 0.0, []
    for i, (name, d) in enumerate(motions):
        start = 0.0 if mode == "parallel" else t if mode == "serial" else i * delay
        out.append((name, round(start, 2), round(start + d, 2)))
        t = start + d
    return out, round(max(e for _, _, e in out), 2)

for mode in ("parallel", "serial", "stagger"):
    rows, total = timeline(mode)
    print(mode, rows, "끝:", total, "초")

deps = {  # 패키지 → 기대는 패키지
    "visibility": [],
    "router": ["visibility"], "video": ["visibility"], "logging": ["visibility"],
    "impression": ["visibility", "logging"], "storage": [], "image": [],
}

def affected(changed):
    out, todo = set(), [changed]
    while todo:
        p = todo.pop()
        for name, ds in deps.items():
            if p in ds and name not in out:
                out.add(name); todo.append(name)
    return sorted(out)

for c in ("visibility", "storage"):
    a = affected(c)
    print(f"{c} 를 고치면 다시 볼 패키지: {a or '없음'} → iOS·Android 테스트 {2*(1+len(a))}번")

per_min = [2, 3, 2, 40, 45, 3, 2, 2]   # 분당 에러 수
threshold = 20
state, log = "ok", []
for m, n in enumerate(per_min):
    if state == "ok" and n >= threshold:
        state = "alert"; log.append(f"{m}분 알림")
    elif state == "alert" and n < threshold:
        state = "resolved(자동)"; log.append(f"{m}분 자동 해제 — 사람 확인 전엔 '완료' 아님")
print(log)
